def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, qty) - sorted by price desc, then arrival_time asc
    sell_book = []  # list of (price, arrival_time, id, qty) - sorted by price asc, then arrival_time asc
    order_map = {}  # id -> (side, price, qty, arrival_time, index_in_book)
    arrival_time = 0

    def match_order(side, price, qty, order_id):
        nonlocal trades, buy_book, sell_book, order_map, arrival_time

        if side == 'buy':
            # Match against sell_book (lowest price first, then earliest arrival)
            while qty > 0 and sell_book:
                sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

                if sell_price <= price:
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])

                    qty -= trade_qty
                    sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

                    if sell_book[0][3] == 0:
                        sell_book.pop(0)
                        if sell_id in order_map:
                            del order_map[sell_id]
                    else:
                        if sell_id in order_map:
                            order_map[sell_id] = (order_map[sell_id][0], order_map[sell_id][1], 
                                                   sell_qty - trade_qty, order_map[sell_id][3], order_map[sell_id][4])
                else:
                    break
        else:  # side == 'sell'
            # Match against buy_book (highest price first, then earliest arrival)
            while qty > 0 and buy_book:
                buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]

                if buy_price >= price:
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])

                    qty -= trade_qty
                    buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

                    if buy_book[0][3] == 0:
                        buy_book.pop(0)
                        if buy_id in order_map:
                            del order_map[buy_id]
                    else:
                        if buy_id in order_map:
                            order_map[buy_id] = (order_map[buy_id][0], order_map[buy_id][1], 
                                                  buy_qty - trade_qty, order_map[buy_id][3], order_map[buy_id][4])
                else:
                    break

        return qty

    for order in orders:
        arrival_time += 1

        if order[0] == 'limit':
            _, order_id, side, price, qty = order

            remaining_qty = match_order(side, price, qty, order_id)

            if remaining_qty > 0:
                if side == 'buy':
                    buy_book.append((price, arrival_time, order_id, remaining_qty))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    order_map[order_id] = (side, price, remaining_qty, arrival_time, len(buy_book) - 1)
                else:  # side == 'sell'
                    sell_book.append((price, arrival_time, order_id, remaining_qty))
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    order_map[order_id] = (side, price, remaining_qty, arrival_time, len(sell_book) - 1)

        elif order[0] == 'ioc':
            _, order_id, side, price, qty = order
            match_order(side, price, qty, order_id)

        elif order[0] == 'market':
            _, order_id, side, qty = order
            if side == 'buy':
                match_order(side, float('inf'), qty, order_id)
            else:  # side == 'sell'
                match_order(side, 0, qty, order_id)

        elif order[0] == 'cancel':
            _, cancel_id = order
            if cancel_id in order_map:
                side, price, remaining_qty, arr_time, _ = order_map[cancel_id]
                if side == 'buy':
                    buy_book = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != cancel_id]
                else:
                    sell_book = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != cancel_id]
                del order_map[cancel_id]

    return trades

